    static var iosTrimEndHandle: String { L("ios.trim_end_handle", table: "Ios") }

    /// Play cut
    ///
    /// Button (with a play symbol) in the Trim video screen of the New Post composer: plays only the part of the video that will be kept.
    static var iosTrimPlayCut: String { L("ios.trim_play_cut", table: "Ios") }

    /// Start of the cut
    ///
    /// Screen-reader name of the left handle of the two-handle slider in the Trim video screen: where the part of the video kept for the post starts. Its value is read as a time (0:02.0).
    static var iosTrimStartHandle: String { L("ios.trim_start_handle", table: "Ios") }

    /// The device didn't answer the connection in time.
    ///
    /// Error given to an action when the connection to the device couldn't be opened in time (nothing answered at its address).
    static var iosWsConnectTimeout: String { L("ios.ws_connect_timeout", table: "Ios") }

    /// Still connecting to the device.
    ///
    /// Error given to an action whose time ran out while the app was still connecting to the device.
    static var iosWsStillConnecting: String { L("ios.ws_still_connecting", table: "Ios") }

    /// The device didn't answer in time.
    ///
    /// Error given to an action (and shown on the card shown over the app when connecting fails) when the device didn't answer a request in time.
    static var iosWsTimedOut: String { L("ios.ws_timed_out", table: "Ios") }

    /// The connection to the device stopped answering.
    ///
    /// Error given to the actions waiting on the connection to the device when it stopped answering and was closed; the app connects again.
    static var iosWsUnresponsive: String { L("ios.ws_unresponsive", table: "Ios") }
}
